CREATE TABLE P_LEW_MART_PIT_ONPREM.T_CNTL_ETL_LOGGING_2 (
	RUN_ID_SEQ NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Sequence number of ETL processing - based on SEQ_CNTL_ETL_LOGGING (see CNTL_ETL_LOGGING_RUN_SEQ)',
	RUN_TS TIMESTAMP_NTZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP() COMMENT 'Execution timestamp. Start of daily ETL processing (see ETL_LOGGING_RUN_SEQ)',
	RUN_DAY_ID DATE NOT NULL DEFAULT TO_DATE('8888-12-31', 'YYYY-MM_2-DD') COMMENT 'Execution day. Format YYYY-MM_2-DD (see ETL_LOGGING_RUN_SEQ).',
	RUN_CLUSTERING_DESC VARCHAR(16777216) NOT NULL DEFAULT '[0]' COMMENT 'Execution cluster in case of parallel execution. Format [ cluster name ]. (see ETL_LOGGING_RUN_SEQ).',
	APPLICATION_NAME VARCHAR(16777216) NOT NULL DEFAULT 'PITonPrem' COMMENT 'General name of the application (see ETL_LOGGING_RUN_SEQ) Name of Application --> Module --> Component',
	MODULE_NAME VARCHAR(16777216) NOT NULL DEFAULT 'N/A' COMMENT 'Name of the program module. Example: POS cash register data processing. Module Name --> Component.',
	COMPONENT_NAME VARCHAR(16777216) NOT NULL DEFAULT 'N/A' COMMENT 'Name of the program component of a program module. Example: POS-ReceiptLine processing',
	START_RUN_TS TIMESTAMP_NTZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP() COMMENT 'Start timestamp of processing',
	END_RUN_TS TIMESTAMP_NTZ(9) COMMENT 'End timestamp of processing',
	RUN_TIME_MIN NUMBER(38,0) AS (DATE_DIFFTIMESTAMPINMINUTES(CAST(START_RUN_TS AS TIMESTAMP_NTZ(9)), CAST(END_RUN_TS AS TIMESTAMP_NTZ(9)))) COMMENT '[VC] Execution time in minutes',
	RUN_TIME_SEC NUMBER(38,0) AS (DATE_DIFFTIMESTAMPINSECONDS(CAST(START_RUN_TS AS TIMESTAMP_NTZ(9)), CAST(END_RUN_TS AS TIMESTAMP_NTZ(9)))) COMMENT '[VC] Execution time in seconds',
	QUERY_TAG VARCHAR(16777216) COMMENT 'Querytag',
	SF_USER VARCHAR(16777216) NOT NULL DEFAULT CURRENT_USER() COMMENT 'Snowflake User - Default =  CURRENT_USER()',
	SF_WAREHOUSE VARCHAR(16777216) NOT NULL DEFAULT CURRENT_WAREHOUSE() COMMENT 'Snowflake Warehouse - Default = CURRENT_WAREHOUSE()',
	SF_ROLE VARCHAR(16777216) NOT NULL DEFAULT CURRENT_ROLE() COMMENT 'Snowflake Role - Default = CURRENT_ROLE()',
	SF_DATABASE VARCHAR(16777216) NOT NULL DEFAULT CURRENT_DATABASE() COMMENT 'Snowflake Database - Default = CURRENT_DATABASE()',
	SF_SCHEMA VARCHAR(16777216) NOT NULL DEFAULT CURRENT_SCHEMA() COMMENT 'Snowflake Schema - Default = CURRENT_SCHEMA()',
	SF_SESSION VARCHAR(16777216) NOT NULL DEFAULT CURRENT_SESSION() COMMENT 'Snowflake Session - Default = CURRENT_SESSION()',
	SF_CLIENT VARCHAR(16777216) NOT NULL DEFAULT CURRENT_CLIENT() COMMENT 'Snowflake Client - Default = CURRENT_CLIENT()',
	RECORD_PROCESSED_NR NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Number of processed Records',
	RUN_LDESC VARCHAR(16777216) AS ('ETL Run [' || (CAST(RUN_ID_SEQ AS VARCHAR(16777216))) || '] on ' || (DAYNAME(RUN_DAY_ID)) || ' ' || (TO_CHAR(CAST(RUN_TS AS TIMESTAMP_NTZ(9)), 'YYYY-MON-DD HH24:MI:SS.FF'))) COMMENT '[VC] Description of the run. Example: ''ETL Run 10 on Thursday 2021-JUL-26 15:37:04.6789'' ',
	START_PROCESSIG_FLAG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag / indicator of the start of the loading run. [0|1]',
	END_PROCESSIG_FLAG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag / indicator of the end of the loading run. [0|1]',
	MODULE_LEVEL_FLAG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag / indicator level Module. [0|1]',
	COMPONENT_LEVEL_FLAG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag / indicator level Component. [0|1]',
	COMPLETED_RUN_FLAG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag / indicator that loading run is completed. [0|1]',
	MOVING_RUN_ID_FROM_CURRENT NUMBER(38,0) DEFAULT 0 COMMENT '[View] Current ID = 0 previous Run IDs are -1,-2,etc.',
	REJECT_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Flag indicates if record was rejected by DQ Rule, e.g. 1/0 or similar data issues',
	REJECT_REASON_ID NUMBER(38,0) NOT NULL DEFAULT -1 COMMENT 'Link to DQ Reject Reason Codes',
	SOURCE_SYSTEM_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Technical Field: Logical Deleted Flag; indicates if the record was logically deleted',
	DELETED_FG NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Logical Deleted Flag; indicates if the record was logically deleted',
	DWH_CREATED_TS TIMESTAMP_NTZ(9) NOT NULL DEFAULT CURRENT_TIMESTAMP() COMMENT 'Timestamp when record was created',
	DWH_UPDATED_TS TIMESTAMP_NTZ(9) COMMENT 'Technical field timestamp when record was updated',
	LOAD_ID NUMBER(38,0) NOT NULL DEFAULT 0 COMMENT 'Technical Field ELT / AB>Initio Process ID',
	UNIQUE (RUN_ID_SEQ),
	PRIMARY KEY (RUN_ID_SEQ, RUN_DAY_ID, DELETED_FG)
)COMMENT='Central ETL Logging Table, holding the start and end timestamps, and the execution run time.'
;